import matplotlib;matplotlib.use('Agg')
import matplotlib.pyplot as plt
from rdkit import Chem
import numpy as np
m=Chem.AddHs(Chem.MolFromSmiles('[N-]1[Si](C)(C)CP(c2ccccc2)C[Si]1(C)C'))
x=np.loadtxt('initial.xyz',skiprows=2,usecols=(1,2,3));els=['Nb','Cl']+[a.GetSymbol() for a in m.GetAtoms()]*2
