for shift in [2,39]:
 for b in m.GetBonds():
  pts=x[[b.GetBeginAtomIdx()+shift,b.GetEndAtomIdx()+shift]]
  ax.plot(*pts.T,c='gray',lw=1)
for i in [1,2,7,39,44]:ax.plot(*x[[0,i]].T,c='purple',lw=2)
colors={'Nb':'purple','Cl':'green','N':'blue','P':'orange','Si':'gold','C':'black','H':'lightgray'}
for i,(el,pt) in enumerate(zip(els,x)):
 ax.scatter(*pt,c=colors[el],s=65 if el!='H' else 8)
 if el not in ['C','H']:ax.text(*pt,el+str(i),fontsize=10)
ax.set_box_aspect([1,1,1]);ax.view_init(elev=15,azim=-70)
